INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷256", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。引文按原文保留，疑似转录讹字单独注明。", "url": "https://github.com/greed-216/histree/blob/fdc81a0b21a4c29dcfb4a4ecc9006df86ffe9248/resources/derived/tongjian/256.txt", "note": "卷256中和四年21段；原始电子文本与SHA-256见来源清单。", "id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "朱玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：朱玫。", "biography": null, "status": "draft", "id": "bb37d3e7-f348-51ea-bc68-8b4355399a19"}, {"name": "李昌符", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李昌符。", "biography": null, "status": "draft", "id": "40f447e6-4770-5e94-9e87-b48375844b3d"}, {"name": "王处存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王处存。", "biography": null, "status": "draft", "id": "8eb58bbe-206e-5b69-af3c-0dd5435bf54b"}, {"name": "冀君武", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：冀君武。", "biography": null, "status": "draft", "id": "72248c16-4c98-541c-a465-46cc38f324e7"}, {"name": "马爽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：马爽。", "biography": null, "status": "draft", "id": "3598b62f-e69b-5c96-bfac-fc2f86519978"}, {"name": "奚忠信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：奚忠信。", "biography": null, "status": "draft", "id": "40abda8f-b499-55f6-9c64-5862b404b362"}, {"name": "孟方立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：孟方立。", "biography": null, "status": "draft", "id": "ec4e71ae-89e4-5b29-aa64-9376ce613174"}, {"name": "乐彦祯", "aliases": ["乐行达"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的乐彦祯：获赐名者。", "biography": null, "status": "draft", "id": "bc42c29a-a3a4-51c5-ad15-16bf1105e036"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "赵犨", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的赵犨，在此段中为陈州守将。", "biography": null, "status": "draft", "id": "1f588420-b0ed-57c6-bb54-1ac4d663c495"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "王绪", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王绪。", "biography": null, "status": "draft", "id": "9fbf20bd-aa87-55f6-8b18-40577932c72a"}, {"name": "王潮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王潮。", "biography": null, "status": "draft", "id": "567ec0f2-e484-5547-a92b-847ea79bbaf4"}, {"name": "董氏（王潮母）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：董氏（王潮母）。", "biography": null, "status": "draft", "id": "c2aba597-78b1-53aa-8157-4bbbf643a255"}, {"name": "刘行全", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：刘行全。", "biography": null, "status": "draft", "id": "598ab61e-1796-5dec-8a17-8677d1635543"}, {"name": "张延鲁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：张延鲁。", "biography": null, "status": "draft", "id": "6a60fde2-1acc-59e8-a494-ea090597325a"}, {"name": "廖彦若", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：廖彦若。", "biography": null, "status": "draft", "id": "8847c526-9148-571d-abd0-86c29de8226b"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "张瑰", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：张瑰。", "biography": null, "status": "draft", "id": "0a92bc80-c524-5b52-96b0-bcb5553c2046"}, {"name": "赵匡", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赵匡。", "biography": null, "status": "draft", "id": "9f984a20-53a8-5a4b-9baf-389ddcbb2ab9"}, {"name": "陈儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的陈儒，在此段中为攻舒州者。", "biography": null, "status": "draft", "id": "ac890eb1-fc70-5b5d-8d09-41f0b4bb8d6c"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "郭璋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：郭璋。", "biography": null, "status": "draft", "id": "5c76517d-deaf-5430-9a0f-0c4743312470"}, {"name": "王徽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王徽。", "biography": null, "status": "draft", "id": "eef76a3e-70c4-5776-8b72-491ffe9d100a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王重荣拒赴兖州，上表指责田令孜", "start_year": 885, "end_year": 885, "time_original": "光启元年七月后条；具体日未载", "dynasty": "唐", "description": "王重荣不肯赴泰宁镇，多次上表指责田令孜离间君臣、列举其十罪；田令孜联络朱玫、李昌符与之抗衡。", "phases": [], "location_name": "河中、兖州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bd7cc33b-3f80-57e1-b97d-d04e79bf4dff"}, {"title": "王处存赴河中受阻，返义武", "start_year": 885, "end_year": 885, "time_original": "光启元年八月", "dynasty": "唐", "description": "王处存上表以卢龙、成德军新退为由请留守易定；朝廷催赴河中。八月他率军到晋州，刺史冀君武闭城不纳，遂返回。", "phases": [], "location_name": "晋州、易定", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b892d55f-b5de-5daf-b098-93ee75ae2d9c"}, {"title": "马爽举兵请诛奚忠信，兵溃后被杀", "start_year": 885, "end_year": 885, "time_original": "光启元年八月后条；具体日未载", "dynasty": "唐", "description": "马爽与奚忠信不和，在邢州南起兵并胁孟方立诛奚忠信；马爽兵溃逃魏州，奚忠信使人贿乐彦祯杀之。", "phases": [], "location_name": "邢州南、魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "17b1c878-9634-51fa-b66f-2fc56a0025c0"}, {"title": "赵犨守陈州，秦宗权未能攻下", "start_year": 885, "end_year": 885, "time_original": "光启元年条；攻守确日未载", "dynasty": "唐", "description": "《通鉴》称秦宗权攻陷邻道多州，陈州刺史赵犨持续抗拒，秦宗权未能使其屈服。", "phases": [], "location_name": "陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "97ff3e9c-cee8-5409-99f6-243859e6e326"}, {"title": "赵犨获任蔡州节度使", "start_year": 885, "end_year": 885, "time_original": "陈州防御期间；具体日未载", "dynasty": "唐", "description": "朝廷任赵犨为蔡州节度使。", "phases": [], "location_name": "蔡州、陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "60cfa588-c3b3-57ea-8b62-0b46abf69317"}, {"title": "赵犨与朱全忠结婚姻", "start_year": 885, "end_year": 885, "time_original": "获朱全忠援助后；具体日未载", "dynasty": "唐", "description": "赵犨感念朱全忠援助，与其结成婚姻关系，朱全忠调发时赵犨及时响应。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "49a94618-db3f-5a54-b0f5-60f5a93b39a1"}, {"title": "王绪欲诛王潮之母，因将士求情而放过", "start_year": 885, "end_year": 885, "time_original": "王绪行至漳州时；具体日未载", "dynasty": "唐", "description": "王绪因道路艰险粮少，禁止军中携带老弱；王潮兄弟仍扶母董氏同行。王绪欲斩董氏，王潮兄弟求先死，将士也求情，董氏得免。", "phases": [], "location_name": "漳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "83f24401-d84a-5532-b9a2-b2644e0ef1db"}, {"title": "王绪疑忌部将，刘行全亦死", "start_year": 885, "end_year": 885, "time_original": "行军至南安前；具体日未载", "dynasty": "唐", "description": "《通鉴》记王绪因望气者言军中有王者气，遂杀勇略或体貌出众的将卒；刘行全亦死，军中惶惧。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "106477d6-5340-57cc-b624-2e8c08508f33"}, {"title": "王潮在南安擒王绪，被推为军将", "start_year": 885, "end_year": 885, "time_original": "行军至南安时；具体日未载", "dynasty": "唐", "description": "王潮说服前锋将，设伏于竹林中擒获王绪；军中相推让，最终奉王潮为将军。", "phases": [], "location_name": "南安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0f20fbb7-c1e3-5e42-b198-9632458656a1"}, {"title": "王潮率军围泉州", "start_year": 885, "end_year": 885, "time_original": "南安夺军权后；具体日未载", "dynasty": "唐", "description": "王潮原拟率兵回光州，至沙县时张延鲁等泉州人请求留下对付泉州刺史廖彦若，王潮遂领兵围泉州。", "phases": [], "location_name": "沙县、泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "11f2b2e5-15f7-57e6-a596-d0d0b22a8706"}, {"title": "陈敬瑄获任三川及峡内军政职", "start_year": 885, "end_year": 885, "time_original": "光启元年九月戊申", "dynasty": "唐", "description": "朝廷任陈敬瑄为三川及峡内诸州指挥、制置等使。", "phases": [], "location_name": "三川及峡内诸州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "673e2a42-019e-598f-82b1-df7fd10550ef"}, {"title": "张瑰杀赵匡和陈儒", "start_year": 885, "end_year": 885, "time_original": "光启元年九月后条；具体日未载", "dynasty": "唐", "description": "蔡州军围荆南，赵匡谋带前节度使陈儒出城，张瑰发现后杀赵匡和陈儒。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6352a14f-cf9c-5eff-a115-42dcd3ca4aa3"}, {"title": "秦宗权在八角击败朱全忠", "start_year": 885, "end_year": 885, "time_original": "光启元年十月癸丑", "dynasty": "唐", "description": "秦宗权在八角击败朱全忠。", "phases": [], "location_name": "八角", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4bbd238a-2714-5ba4-87d9-b35387433eef"}, {"title": "王重荣请李克用援助", "start_year": 885, "end_year": 885, "time_original": "八角战后、十一月前；具体日未载", "dynasty": "唐", "description": "王重荣向李克用求援，劝其先消除朝廷近侧对手，再与朱全忠作战。李克用上表称朱玫、李昌符与朱全忠共同威胁自己，并说明将来出兵打算；朝廷多次遣使劝解。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4c8edddc-0f08-5f7c-8791-4a0d9aee07dc"}, {"title": "朱玫派人扰乱京师并嫁祸李克用", "start_year": 885, "end_year": 885, "time_original": "王重荣求援后；具体日未载", "dynasty": "唐", "description": "《通鉴》记朱玫遣人潜入京城，焚烧储物或刺杀近侍，声称为李克用所为，导致京城恐慌。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a789f404-7dfd-5468-98e0-ff8b0cc567cc"}, {"title": "田令孜遣朱玫等屯沙苑讨王重荣", "start_year": 885, "end_year": 885, "time_original": "光启元年十一月前后", "dynasty": "唐", "description": "田令孜遣朱玫、李昌符率本军及神策诸军屯沙苑讨王重荣。王重荣发兵抵御并再次请李克用援助，李克用率军赶来。", "phases": [], "location_name": "沙苑、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dfd93573-689d-5314-b880-b7d28c47a818"}, {"title": "王重荣部攻同州，郭璋战死", "start_year": 885, "end_year": 885, "time_original": "光启元年十一月", "dynasty": "唐", "description": "王重荣遣兵攻同州，刺史郭璋出战失败身死。", "phases": [], "location_name": "同州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "64fe69cb-af4c-5cd8-b709-4f38e3a738ec"}, {"title": "李克用、王重荣在沙苑击败朱玫、李昌符", "start_year": 885, "end_year": 885, "time_original": "光启元年十二月癸酉", "dynasty": "唐", "description": "李克用与王重荣军在沙苑交战，朱玫、李昌符战败退回本镇；溃军沿途焚掠。此前双方相持一个多月，朝廷和解诏令未被李克用接受。", "phases": [], "location_name": "沙苑", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e92a7c91-a287-5ce4-a1d7-f80a655e0135"}, {"title": "田令孜奉僖宗出长安奔凤翔", "start_year": 885, "end_year": 885, "time_original": "光启元年十二月乙亥夜", "dynasty": "唐", "description": "李克用军进逼京城；田令孜奉皇帝夜出开远门，前往凤翔。", "phases": [], "location_name": "长安、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b498401-9eb0-5c93-a36b-bec7667141aa"}, {"title": "长安在兵乱中再次遭焚掠", "start_year": 885, "end_year": 885, "time_original": "光启元年十二月车驾出奔前后", "dynasty": "唐", "description": "《通鉴》追述黄巢退后长安已多次被焚掠，王徽多年补葺；至此次兵乱，宫室及城中建筑再次被乱兵焚掠。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cbbe7b60-1280-5c02-951c-46e896de9dc4"}, {"title": "河中军获赐号护国", "start_year": 885, "end_year": 885, "time_original": "光启元年是岁；具体月日未载", "dynasty": "唐", "description": "朝廷赐河中军号“护国”。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0d27d4de-1b79-5b99-8302-b31640030855"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

